## 4️⃣ Full minimal example (v6)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre – custom pin</title>
  <link href="https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.mjs';

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://tiles.openfreemap.org/styles/liberty', // any style with a valid sprite
    center: [-122.42, 37.78],
    zoom: 12
  });

  map.on('load', async () => {
    try {
      const { data: img } = await map.loadImage(
        'https://raw.githubusercontent.com/maplibre/maplibre-gl-js/main/docs/assets/pin.png'
      );
      // Register the image under the name "my-pin"
      map.addImage('my-pin', img);

      // Use it in a Symbol layer
      map.addSource('pin-point', {
        type: 'geojson',
        data: {
          type: 'FeatureCollection',
          features: [{
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [-122.42, 37.78] }
          }]
        }
      });

      map.addLayer({
        id: 'pin-layer',
        type: 'symbol',
        source: 'pin-point',
        layout: {
          'icon-image': 'my-pin',
          'icon-size': 1
        }
      });
    } catch (e) {
      console.error('Could not load pin image', e);
    }
  });
</script>
</body>
</html>
```

Run the snippet (or copy it into a local file) and you’ll see a pin rendered exactly as you would with Mapbox GL JS, but using the **Promise-based** `loadImage` API.

